package org.hyperledger.iroha.sdk.offline.wallet

import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertNull
import org.junit.jupiter.api.Test

class KagemushaWalletSuffixUnloadV1Test {
    private val amount = KagemushaWalletUInt128V1(1, 0)
    private fun request(quote: ByteArray? = null, certificates: ByteArray? = null, beneficiary: ByteArray? = null) =
        KagemushaWalletSuffixUnloadRequestV1(ByteArray(32) { 1 }, amount, quote, certificates, beneficiary)

    @Test fun `charge originals are inseparable and bounded before copying`() {
        assertNull(request().quote())
        for (mask in 1..6) assertFailsWith<IllegalArgumentException> {
            request(if (mask and 1 != 0) byteArrayOf(1) else null,
                if (mask and 2 != 0) byteArrayOf(2) else null,
                if (mask and 4 != 0) byteArrayOf(3) else null)
        }
        for ((quote, certificates, beneficiary) in listOf(
            Triple(ByteArray(0), byteArrayOf(1), byteArrayOf(1)),
            Triple(ByteArray(1_025), byteArrayOf(1), byteArrayOf(1)),
            Triple(byteArrayOf(1), ByteArray(10_035), byteArrayOf(1)),
            Triple(byteArrayOf(1), byteArrayOf(1), ByteArray(4_097)),
        )) assertFailsWith<IllegalArgumentException> { request(quote, certificates, beneficiary) }
    }

    @Test fun `request originals cannot be changed after selection`() {
        val id = ByteArray(32) { 1 }; val quote = byteArrayOf(2); val certificates = byteArrayOf(3); val beneficiary = byteArrayOf(4)
        val selected = KagemushaWalletSuffixUnloadRequestV1(id, amount, quote, certificates, beneficiary)
        listOf(id, quote, certificates, beneficiary).forEach { it.fill(0) }
        listOfNotNull(selected.requestId(), selected.quote(), selected.certificates(), selected.beneficiary()).forEach { it.fill(0) }
        assertContentEquals(ByteArray(32) { 1 }, selected.requestId())
        assertContentEquals(byteArrayOf(2), selected.quote())
        assertContentEquals(byteArrayOf(3), selected.certificates())
        assertContentEquals(byteArrayOf(4), selected.beneficiary())
    }

    @Test fun `request uses lossless u128 and nonzero identity`() {
        for (id in listOf(ByteArray(31) { 1 }, ByteArray(32), ByteArray(33) { 1 })) {
            assertFailsWith<IllegalArgumentException> { KagemushaWalletSuffixUnloadRequestV1(id, amount) }
        }
        assertFailsWith<IllegalArgumentException> {
            KagemushaWalletSuffixUnloadRequestV1(ByteArray(32) { 1 }, KagemushaWalletUInt128V1(0, 0))
        }
        val large = KagemushaWalletUInt128V1(-1, -1)
        assertEquals(large, KagemushaWalletSuffixUnloadRequestV1(ByteArray(32) { 1 }, large).amount)
    }

    @Test fun `stage confirmation and payout keep distinct tags and exact certified identity`() {
        for (kind in listOf(69, 70, 76)) {
            val reply = KagemushaWalletSuffixUnloadReplyV1(kind, -1, 0, -1, 0, 0, ByteArray(32) { 5 })
            assertEquals(kind, reply.status)
            reply.bytes().fill(0)
            assertContentEquals(ByteArray(32) { 5 }, reply.bytes())
            for (height in listOf(0L, 1L)) assertFailsWith<KagemushaWalletExceptionV1> {
                KagemushaWalletSuffixUnloadReplyV1(kind, -1, 0, height, 0, 0, ByteArray(32) { 5 })
            }
            assertFailsWith<KagemushaWalletExceptionV1> {
                KagemushaWalletSuffixUnloadReplyV1(kind, -1, 0, 2, 0, 0, ByteArray(32))
            }
        }
    }

    @Test fun `only absent attempt readback can have empty successful original`() {
        assertContentEquals(byteArrayOf(), KagemushaWalletSuffixUnloadReplyV1(78, -1, 0, 0, 0, 0, byteArrayOf()).bytes())
        for (kind in listOf(72, 73, 74, 75, 77)) assertFailsWith<KagemushaWalletExceptionV1> {
            KagemushaWalletSuffixUnloadReplyV1(kind, -1, 0, if (kind == 73) 1 else 0, 0, 0, byteArrayOf())
        }
        assertFailsWith<KagemushaWalletExceptionV1> {
            KagemushaWalletSuffixUnloadReplyV1(78, -1, 0, 0, 0, 0,
                ByteArray(KagemushaWalletSuffixUnloadV1.SIGNED_WIRE_MAX_BYTES + 1))
        }
        assertFailsWith<KagemushaWalletExceptionV1> {
            KagemushaWalletSuffixUnloadReplyV1(65, -1, 0, 7, 0, 2, byteArrayOf())
        }
    }
    // Canonical fixtures generated by native-vectors.rs from the exact Rust DATA definitions.
    private fun fixture(name: String): ByteArray = fixtures.getValue(name).chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    private val fixtures = mapOf(
        "carriage-append" to "",
        "carriage-begin" to "",
        "carriage-finalize" to "",
        "carriage-ordinary" to "4e52543000008eef66c2b4be9ed7b2604aec85793350003000000000000000f000acc7e807d03f0200000000000000002002020202020202020202020202020202020202020202020202020202020202020e0600000009010000000000000005",
        "progress-17-of-50" to "4e525430000035bc1e23b48598d658d3d844fb9430d60049000000000000007bae5fc72abb1eb3020000000000000000020100020e0020010101010101010101010101010101010101010101010101010101010101010110110000000000000000000000000000001032000000000000000000000000000000",
        "released-u128" to "",
        "review-charge-u128" to "",
        "review-no-charge-u128" to "",
        "status-initializing" to "4e52543000001f08d2aade36cb47c6e43694bd101e1e0034000000000000003d510cd9316a3d25020000000000000000020100020f0002000002000001000100010010000000000000000000000000000000001000000000000000000000000000000000",
        "status-verifying-u128" to "",
    )

    @Test fun `canonical Rust projections preserve every stage count and wide amount`() {
        val progress = KagemushaWalletSuffixUnloadProgressV1(fixture("progress-17-of-50"))
        assertEquals(KagemushaWalletUInt128V1(17, 0), progress.completedSteps)
        assertEquals(KagemushaWalletUInt128V1(50, 0), progress.totalSteps)
        val status = KagemushaWalletSuffixUnloadStatusV1(fixture("status-verifying-u128"))
        assertEquals(KagemushaWalletUInt128V1(99, 1), status.currentSequence)
        assertEquals(KagemushaWalletUInt128V1(49, 1), status.foldedSequence)
        assertContentEquals(ByteArray(32) { 1 }, status.requestId())
        val empty = KagemushaWalletSuffixUnloadStatusV1(fixture("status-initializing"))
        assertNull(empty.requestId()); assertNull(empty.currentSequence); assertNull(empty.foldedSequence)
        val released = KagemushaWalletSuffixUnloadReleasedV1(fixture("released-u128"))
        assertEquals(KagemushaWalletUInt128V1(123, 1), released.amount)
        assertEquals(KagemushaWalletUInt128V1(9, 0), released.instructionCount)
        for ((name, fee) in listOf("review-no-charge-u128" to 0L, "review-charge-u128" to 17L)) {
            val review = KagemushaWalletSuffixUnloadReviewProjectionV1(fixture(name))
            assertEquals(KagemushaWalletUInt128V1(123, 1), review.amount)
            assertEquals(KagemushaWalletUInt128V1(fee, 0), review.charge)
            assertEquals(KagemushaWalletUInt128V1(123 - fee, 1), review.netDestinationAmount)
            assertEquals(released.stepCount, review.stepCount)
            assertEquals(released.chunkCount, review.chunkCount)
            assertEquals(released.instructionCount, review.instructionCount)
        }
    }

    @Test fun `canonical frames reject truncation trailing bytes wrong schema and changed payload`() {
        val original = fixture("review-no-charge-u128")
        for (bad in listOf(original.copyOf(original.size - 1), original + 0,
            original.copyOf().also { it[10] = (it[10].toInt() xor 1).toByte() },
            original.copyOf().also { it[it.lastIndex] = (it.last().toInt() xor 1).toByte() },
            fixture("released-u128"))) {
            assertFailsWith<KagemushaWalletExceptionV1> { KagemushaWalletSuffixUnloadReviewProjectionV1(bad) }
        }
    }

    @Test fun `issued review is owner bound single use and only exact retained token restores it`() {
        val owner = Any()
        val reply = KagemushaWalletSuffixUnloadReplyV1(73, -1, 0, 42, 0, 0, fixture("review-no-charge-u128"))
        val ready = reply.decision(owner, ByteArray(32) { 1 }) as KagemushaWalletSuffixUnloadDecisionV1.Ready
        assertFailsWith<IllegalArgumentException> { ready.review.consume(Any()) }
        val token = ready.review.consume(owner)
        assertEquals(42L, token)
        assertFailsWith<KagemushaWalletExceptionV1> { ready.review.consume(owner) }
        assertFailsWith<KagemushaWalletExceptionV1> {
            KagemushaWalletSuffixUnloadReplyV1(65, -1, 0, 43, 0, 6, byteArrayOf()).execution(owner, ready.review, token)
        }
        KagemushaWalletSuffixUnloadReplyV1(65, -1, 0, 42, 0, 6, byteArrayOf()).execution(owner, ready.review, token)
        assertEquals(42L, ready.review.consume(owner))
        val executed = KagemushaWalletSuffixUnloadReplyV1(74, -1, 0, 0, 0, 0, fixture("released-u128"))
            .execution(owner, ready.review, token) as KagemushaWalletSuffixUnloadExecutionV1.Released
        assertEquals(ready.review.projection.amount, executed.summary.amount)
        assertFailsWith<KagemushaWalletExceptionV1> { ready.review.consume(owner) }
        assertFailsWith<KagemushaWalletExceptionV1> { reply.decision(owner, ByteArray(32) { 2 }) }
    }

    @Test fun `suffix carriage accepts only canonical suffix action shapes`() {
        for (name in listOf("carriage-begin", "carriage-append", "carriage-finalize")) {
            val frame = fixture(name)
            assertContentEquals(frame, KagemushaWalletSuffixUnloadV1.instructionOriginal(frame))
            assertFailsWith<KagemushaWalletExceptionV1> { KagemushaWalletSuffixUnloadV1.instructionOriginal(frame + 0) }
        }
        assertFailsWith<KagemushaWalletExceptionV1> { KagemushaWalletSuffixUnloadV1.instructionOriginal(fixture("carriage-ordinary")) }
        assertFailsWith<KagemushaWalletExceptionV1> { KagemushaWalletSuffixUnloadV1.instructionOriginal(fixture("released-u128")) }
        assertFailsWith<KagemushaWalletExceptionV1> { KagemushaWalletSuffixUnloadV1.instructionOriginal(ByteArray(KagemushaWalletSuffixUnloadV1.INSTRUCTION_MAX_BYTES + 1)) }
    }

}
